public class Main {
    static int n;
    static int[] costs;
    static char[][] adj;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        sc.nextLine();

        costs = new int[n];
        String[] costStr = sc.nextLine().split(" ");
        for (int i = 0; i < n; i++) {
            costs[i] = Integer.parseInt(costStr[i]);
        }

        adj = new char[n][n];
        for (int i = 0; i < n; i++) {
            String row = sc.nextLine().replace(" ", "");
            adj[i] = row.toCharArray();
        }

        double minAvg = Double.MAX_VALUE;

        for (int mask = 1; mask < (1 << n); mask++) {
            List<Integer> stations = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    stations.add(i);
                }
            }

            if (canReachAll(stations)) {
                int totalCost = 0;
                for (int s : stations) {
                    totalCost += costs[s];
                }
                double avg = (double) totalCost / stations.size();
                minAvg = Math.min(minAvg, avg);
            }
        }

        System.out.println(minAvg);
    }

    static boolean canReachAll(List<Integer> stations) {
        if (stations.isEmpty()) return false;

        boolean[] visited = new boolean[n];
        Queue<Integer> queue = new LinkedList<>();

        for (int s : stations) {
            visited[s] = true;
            queue.offer(s);
        }

        while (!queue.isEmpty()) {
            int u = queue.poll();
            for (int v = 0; v < n; v++) {
                if (adj[u][v] == 'Y' && !visited[v]) {
                    visited[v] = true;
                    queue.offer(v);
                }
            }
        }

        for (boolean v : visited) {
            if (!v) return false;
        }
        return true;
    }
}

