public class Main {
    static int n, m;
    static int[][] grid;
    static int minCost;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();

        grid = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                grid[i][j] = sc.nextInt();
            }
        }

        minCost = 0;

        for (int mask = 0; mask < (1 << (n * m)); mask++) {
            if (isConnected(mask)) {
                int cost = calculateCost(mask);
                minCost = Math.min(minCost, cost);
            }
        }

        System.out.println(minCost);
    }

    static boolean isConnected(int mask) {
        if (mask == 0) return true;

        List<Integer> cells = new ArrayList<>();
        for (int i = 0; i < n * m; i++) {
            if ((mask & (1 << i)) != 0) {
                cells.add(i);
            }
        }

        if (cells.isEmpty()) return true;

        boolean[] visited = new boolean[n * m];
        Queue<Integer> queue = new LinkedList<>();
        queue.offer(cells.get(0));
        visited[cells.get(0)] = true;
        int count = 1;

        while (!queue.isEmpty()) {
            int curr = queue.poll();
            int r = curr / m;
            int c = curr % m;

            int[] dr = {-1, 1, 0, 0};
            int[] dc = {0, 0, -1, 1};

            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];
                if (nr >= 0 && nr < n && nc >= 0 && nc < m) {
                    int next = nr * m + nc;
                    if ((mask & (1 << next)) != 0 && !visited[next]) {
                        visited[next] = true;
                        queue.offer(next);
                        count++;
                    }
                }
            }
        }

        return count == cells.size();
    }

    static int calculateCost(int mask) {
        int cost = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if ((mask & (1 << (i * m + j))) != 0) {
                    cost += grid[i][j];
                }
            }
        }
        return cost;
    }
}

