        List<String> dictWords = new ArrayList<>();

        while (true) {
            String word = sc.nextLine();
            if (word.equals("-")) break;
            dictWords.add(word);
        }

        while (true) {
            String puzzle = sc.nextLine();
            if (puzzle.equals("#")) break;

            Map<Character, Integer> puzzleCounter = new HashMap<>();
            for (char c : puzzle.toCharArray()) {
                puzzleCounter.put(c, puzzleCounter.getOrDefault(c, 0) + 1);
            }

            Set<Character> uniqueLetters = new TreeSet<>(puzzleCounter.keySet());
            Map<Character, Integer> letterCounts = new HashMap<>();
            for (char letter : uniqueLetters) {
                letterCounts.put(letter, 0);
            }

            for (String word : dictWords) {
                Map<Character, Integer> wordCounter = new HashMap<>();
                for (char c : word.toCharArray()) {
                    wordCounter.put(c, wordCounter.getOrDefault(c, 0) + 1);
                }

                boolean canMake = true;
                for (Map.Entry<Character, Integer> entry : wordCounter.entrySet()) {
                    char ch = entry.getKey();
                    int count = entry.getValue();
                    if (!puzzleCounter.containsKey(ch) || puzzleCounter.get(ch) < count) {
                        canMake = false;
                        break;
                    }
                }

                if (canMake) {
                    for (char letter : uniqueLetters) {
                        if (word.indexOf(letter) >= 0) {
                            letterCounts.put(letter, letterCounts.get(letter) + 1);
                        }
                    }
                }
            }

            int minCount = Integer.MAX_VALUE;
            int maxCount = Integer.MIN_VALUE;

